/* @socom-skeleton body Tick__14CSched_ManagerFf */
bool CSched_Manager::Tick(f32 dT)
{
	m_inTick = true;
	for (auto i = begin(); i != end(); ++i)
	{
		CSched_Task* task = *i;
		bool ran = false;

		if (!task->m_removed)
		{
			m_priority = task->m_priority;

			if (!task->m_func)
				ran = true;
			else
				ran = task->m_func(dT, task->m_registrar);
		}
	}
	m_inTick = false;
	return true;
}

